1	'use client'
2	
3	import { useState, useCallback, useEffect, useMemo } from 'react'
4	import { useSearchParams, useRouter } from 'next/navigation'
5	import { Users, SearchX, BookmarkX, Plus, Loader2 } from 'lucide-react'
6	import { toast } from 'sonner'
7	import { Button } from '@/components/ui/button'
8	import { ClientsTable } from '@/components/clients/ClientsTable'
9	import { ClientsToolbar } from '@/components/clients/ClientsToolbar'
10	import { ClientsViewTabs } from '@/components/clients/ClientsViewTabs'
11	import { BulkActionsBar } from '@/components/clients/BulkActionsBar'
12	import type { ClientView } from '@/components/clients/SavedViewSwitcher'
13	import { SavedViewManager } from '@/components/clients/SavedViewManager'
14	import { ClientDrawer } from '@/components/clients/ClientDrawer'
15	import dynamic from 'next/dynamic'
16	import { Skeleton } from '@/components/ui/skeleton'
17	
18	// B3 fix: code-split Tiptap out of the /clients route initial bundle (~130KB)
19	const AddNoteModal = dynamic(
20	  () => import('@/components/clients/notes/AddNoteModal').then((m) => ({ default: m.AddNoteModal })),
21	  { ssr: false, loading: () => <Skeleton className="h-10 w-full rounded-lg" /> },
22	)
23	import { DataState } from '@/components/shared/DataState'
24	import { EmptyState } from '@/components/shared/EmptyState'
25	import { PageError } from '@/components/shared/PageError'
26	import { PullToRefresh } from '@/components/shared/PullToRefresh'
27	import { TableSkeleton } from '@/components/skeletons'
28	import type { ClientTag } from '@/components/clients/TagChip'
29	import type { Database } from '@/lib/supabase/types'
30	import type { ColumnDef } from '@/components/clients/ColumnsPicker'
31	import type { SortKey } from '@/components/clients/SortDropdown'
32	import {
33	  buildClientListSearchParams,
34	  CLIENT_LIST_PAGE_SIZE,
35	  isClientListLastVisitRange,
36	  isClientListSpendingTier,
37	  isClientListSort,
38	} from '@/lib/clients/list-query'
39	import {
40	  DEFAULT_FILTERS,
41	  type ClientFilters,
42	} from '@/components/clients/filters-types'
43	
44	type Client = Database['public']['Tables']['clients']['Row']
45	
46	// ── Column definitions ──────────────────────────────────────────────────────
47	const COLUMN_DEFS: ColumnDef[] = [
48	  { key: 'client',     label: 'Client',    alwaysVisible: true },
49	  { key: 'tags',       label: 'Tags' },
50	  { key: 'last_visit', label: 'Last visit' },
51	  { key: 'spent',      label: 'Spent' },
52	  { key: 'sessions',   label: 'Sessions' },
53	  { key: 'source',     label: 'Source' },
54	  { key: 'contact',    label: 'Contact' },
55	]
56	
57	const COLUMN_STORAGE_KEY = 'clients.columns.v1'
58	
59	function getClientListErrorMessage(payload: unknown): string | null {
60	  if (
61	    payload &&
62	    typeof payload === 'object' &&
63	    'error' in payload &&
64	    typeof payload.error === 'string'
65	  ) {
66	    return payload.error
67	  }
68	  return null
69	}
70	
71	function getInitialVisibleKeys(): string[] {
72	  if (typeof window === 'undefined') return COLUMN_DEFS.map((c) => c.key)
73	  try {
74	    const stored = window.localStorage.getItem(COLUMN_STORAGE_KEY)
75	    if (stored) {
76	      const parsed = JSON.parse(stored) as unknown
77	      if (Array.isArray(parsed) && parsed.every((k) => typeof k === 'string')) {
78	        return parsed as string[]
79	      }
80	    }
81	  } catch {
82	    // Ignore — fall back to defaults
83	  }
84	  return COLUMN_DEFS.map((c) => c.key)
85	}
86	
87	function toStringArray(value: unknown): string[] {
88	  if (!Array.isArray(value)) return []
89	  return value.filter((item): item is string => typeof item === 'string')
90	}
91	
92	function normalizeClientFilterTags(
93	  tags: unknown,
94	  tagLibrary: ClientTag[],
95	): string[] {
96	  return [...new Set(toStringArray(tags).map((token) => {
97	    const match = tagLibrary.find((tag) => tag.id === token || tag.name === token)
98	    return match?.name ?? token
99	  }))]
100	}
101	
102	function normalizeViewFilters(
103	  rawFilters: Partial<ClientFilters>,
104	  tagLibrary: ClientTag[],
105	): ClientFilters {
106	  const q = typeof rawFilters.q === 'string' ? rawFilters.q : ''
107	  const vip = rawFilters.vip === true
108	  const inactive = rawFilters.inactive === true
109	  const noShows = rawFilters.noShows === true
110	  const showArchived = rawFilters.showArchived === true
111	  const hasAlerts = rawFilters.hasAlerts === true
112	  const spendingTier =
113	    typeof rawFilters.spendingTier === 'string' &&
114	    isClientListSpendingTier(rawFilters.spendingTier)
115	      ? rawFilters.spendingTier
116	      : ''
117	  const lastVisitRange =
118	    typeof rawFilters.lastVisitRange === 'string' &&
119	    isClientListLastVisitRange(rawFilters.lastVisitRange)
120	      ? rawFilters.lastVisitRange
121	      : ''
122	
123	  return {
124	    ...DEFAULT_FILTERS,
125	    q,
126	    vip,
127	    inactive,
128	    noShows,
129	    showArchived,
130	    hasAlerts,
131	    spendingTier,
132	    tags: normalizeClientFilterTags(rawFilters.tags, tagLibrary),
133	    artistIds: toStringArray(rawFilters.artistIds),
134	    serviceIds: toStringArray(rawFilters.serviceIds),
135	    lastVisitRange,
136	  }
137	}
138	
139	// ────────────────────────────────────────────────────────────────────────────
140	
141	interface ClientsPageClientProps {
142	  initialClients: Client[]
143	  tagLibrary: ClientTag[]
144	}
145	
146	export function ClientsPageClient({ initialClients, tagLibrary }: ClientsPageClientProps) {
147	  const router = useRouter()
148	  const searchParams = useSearchParams()
149	
150	  const [clients, setClients] = useState<Client[]>(initialClients)
151	  const [filters, setFilters] = useState<ClientFilters>(DEFAULT_FILTERS)
152	  const [selectedIds, setSelectedIds] = useState<string[]>([])
153	  const [loading, setLoading] = useState(false)
154	  const [fetchError, setFetchError] = useState<Error | null>(null)
155	  const [drawerOpen, setDrawerOpen] = useState(false)
156	  const [editingClient, setEditingClient] = useState<Client | null>(null)
157	  const [noteClientId, setNoteClientId] = useState<string | null>(null)
158	  const [page, setPage] = useState(1)
159	  const [hasMore, setHasMore] = useState(false)
160	  const [totalCount, setTotalCount] = useState<number | null>(null)
161	
162	  // Saved views
163	  const [views, setViews] = useState<ClientView[]>([])
164	  const [activeViewId, setActiveViewId] = useState<string | null>(null)
165	  const [viewManagerOpen, setViewManagerOpen] = useState(false)
166	  const [viewManagerMode, setViewManagerMode] = useState<'create' | 'edit'>('create')
167	  const [editingView, setEditingView] = useState<ClientView | null>(null)
168	  const [hasUnsavedChanges, setHasUnsavedChanges] = useState(false)
169	
170	  // Sort + column visibility
171	  const [sort, setSort] = useState<SortKey>(() => {
172	    if (typeof window !== 'undefined') {
173	      const sp = new URLSearchParams(window.location.search)
174	      const sortParam = sp.get('sort')
175	      if (sortParam && isClientListSort(sortParam)) {
176	        return sortParam
177	      }
178	    }
179	    return 'last_visit_desc'
180	  })
181	  const [visibleColumnKeys, setVisibleColumnKeys] = useState<string[]>(getInitialVisibleKeys)
182	
183	  // Persist column visibility to localStorage
184	  useEffect(() => {
185	    try {
186	      window.localStorage.setItem(COLUMN_STORAGE_KEY, JSON.stringify(visibleColumnKeys))
187	    } catch {
188	      // Ignore storage errors
189	    }
190	  }, [visibleColumnKeys])
191	
192	  // Persist sort to URL
193	  useEffect(() => {
194	    router.replace(
195	      sort !== 'last_visit_desc'
196	        ? `?sort=${sort}`
197	        : (searchParams.get('page') ? `?page=${searchParams.get('page')}` : ''),
198	      { scroll: false }
199	    )
200	  // eslint-disable-next-line react-hooks/exhaustive-deps
201	  }, [sort])
202	
203	  const fetchViews = useCallback(async () => {
204	    try {
205	      const res = await fetch('/api/client-views')
206	      if (res.ok) {
207	        const json = await res.json() as { data: ClientView[] }
208	        setViews(json.data ?? [])
209	        const defaultView = json.data?.find((v) => v.is_default)
210	        if (defaultView) {
211	          setActiveViewId((prev) => prev ?? defaultView.id)
212	        }
213	      }
214	    } catch {
215	      toast.error('Failed to load views', { description: 'Using All clients as default' })
216	    }
217	  }, [])
218	
219	  useEffect(() => {
220	    void fetchViews()
221	  }, [fetchViews])
222	
223	  // Restore page from URL
224	  useEffect(() => {
225	    const p = parseInt(searchParams.get('page') ?? '1', 10)
226	    if (p > 1) {
227	      setPage(p)
228	    }
229	  }, []) // eslint-disable-line react-hooks/exhaustive-deps
230	
231	  const fetchClients = useCallback(async (f: ClientFilters, p = 1, sortKey: SortKey = 'last_visit_desc') => {
232	    setLoading(true)
233	    setFetchError(null)
234	    try {
235	      const params = buildClientListSearchParams({
236	        filters: f,
237	        page: p,
238	        perPage: CLIENT_LIST_PAGE_SIZE,
239	        sort: sortKey,
240	      })
241	      const res = await fetch(`/api/clients?${params.toString()}`)
242	      if (!res.ok) {
243	        const payload = await res.json().catch(() => null)
244	        throw new Error(getClientListErrorMessage(payload) ?? 'Failed to load clients')
245	      }
246	      const json = await res.json() as { data: Client[]; count: number }
247	
248	      if (p === 1) {
249	        setClients(json.data ?? [])
250	      } else {
251	        setClients((prev) => [...prev, ...(json.data ?? [])])
252	      }
253	      setTotalCount(json.count ?? null)
254	      setHasMore((json.data?.length ?? 0) >= CLIENT_LIST_PAGE_SIZE)
255	    } catch (err) {
256	      setFetchError(err instanceof Error ? err : new Error('Failed to load clients'))
257	    } finally {
258	      setLoading(false)
259	    }
260	  }, [])
261	
262	  useEffect(() => {
263	    void fetchClients(filters, 1, sort)
264	    setPage(1)
265	    setSelectedIds([])
266	  }, [filters, sort, fetchClients])
267	
268	  function handleFiltersChange(f: ClientFilters) {
269	    setFilters(f)
270	    setHasUnsavedChanges(true)
271	  }
272	
273	  function handleViewChange(viewId: string | null) {
274	    setActiveViewId(viewId)
275	    setHasUnsavedChanges(false)
276	    const view = views.find((v) => v.id === viewId)
277	    if (view) {
278	      const viewFilters = view.filters as Partial<ClientFilters>
279	      setFilters(normalizeViewFilters(viewFilters, tagLibrary))
280	    } else {
281	      setFilters(DEFAULT_FILTERS)
282	    }
283	  }
284	
285	  async function handleDeleteView(viewId: string) {
286	    try {
287	      const res = await fetch(`/api/client-views/${viewId}`, { method: 'DELETE' })
288	      if (!res.ok) throw new Error('Failed to delete view')
289	      setViews((prev) => prev.filter((v) => v.id !== viewId))
290	      if (activeViewId === viewId) {
291	        const defaultView = views.find((v) => v.is_default)
292	        setActiveViewId(defaultView?.id ?? null)
293	      }
294	      toast.success('View deleted')
295	    } catch {
296	      toast.error('Failed to delete view')
297	    }
298	  }
299	
300	  async function handleDuplicateView(view: ClientView) {
301	    try {
302	      const res = await fetch('/api/client-views', {
303	        method: 'POST',
304	        headers: { 'Content-Type': 'application/json' },
305	        body: JSON.stringify({
306	          name: `${view.name} (copy)`,
307	          filters: view.filters,
308	          scope: 'private',
309	        }),
310	      })
311	      if (!res.ok) throw new Error('Failed to duplicate view')
312	      const json = await res.json() as { data: ClientView }
313	      setViews((prev) => [...prev, json.data])
314	      toast.success('View duplicated')
315	    } catch {
316	      toast.error('Failed to duplicate view')
317	    }
318	  }
319	
320	  async function handleSetDefaultView(view: ClientView) {
321	    try {
322	      const res = await fetch(`/api/client-views/${view.id}`, {
323	        method: 'PATCH',
324	        headers: { 'Content-Type': 'application/json' },
325	        body: JSON.stringify({ is_default: true }),
326	      })
327	      if (!res.ok) throw new Error('Failed to set default')
328	      setViews((prev) => prev.map((v) => ({ ...v, is_default: v.id === view.id })))
329	      toast.success(`"${view.name}" is now your default view`)
330	    } catch {
331	      toast.error('Failed to set default view')
332	    }
333	  }
334	
335	  function handleViewSaved(savedView: ClientView) {
336	    setViews((prev) => {
337	      const idx = prev.findIndex((v) => v.id === savedView.id)
338	      if (idx >= 0) {
339	        const next = [...prev]
340	        next[idx] = savedView
341	        return next
342	      }
343	      return [...prev, savedView]
344	    })
345	    setActiveViewId(savedView.id)
346	    setHasUnsavedChanges(false)
347	  }
348	
349	  function handleLoadMore() {
350	    const nextPage = page + 1
351	    setPage(nextPage)
352	    router.replace(`?page=${nextPage}`, { scroll: false })
353	    void fetchClients(filters, nextPage, sort)
354	  }
355	
356	  function handleEditClient(client: Client) {
357	    setEditingClient(client)
358	    setDrawerOpen(true)
359	  }
360	
361	  function handleNewClient() {
362	    setEditingClient(null)
363	    setDrawerOpen(true)
364	  }
365	
366	  function handleDrawerSuccess(client: Client) {
367	    setClients((prev) => {
368	      const idx = prev.findIndex((c) => c.id === client.id)
369	      if (idx >= 0) {
370	        const next = [...prev]
371	        next[idx] = client
372	        return next
373	      }
374	      return [client, ...prev]
375	    })
376	    void fetchClients(filters, 1, sort)
377	  }
378	
379	  const hasActiveFilters = !!(
380	    filters.q || filters.tags.length > 0 || filters.vip ||
381	    filters.inactive || filters.noShows || filters.spendingTier ||
382	    filters.artistIds.length > 0 || filters.serviceIds.length > 0 || filters.lastVisitRange
383	  )
384	
385	  const inactiveCount = useMemo(() => {
386	    const cutoff = Date.now() - 90 * 24 * 60 * 60 * 1000
387	    return clients.filter(
388	      (c) => !c.archived_at && c.last_visit_at !== null && new Date(c.last_visit_at).getTime() < cutoff
389	    ).length
390	  }, [clients])
391	
392	  const isInitialLoad = loading && clients.length === 0
393	
394	  return (
395	    <PullToRefresh
396	      onRefresh={async () => { router.refresh() }}
397	      className="flex flex-col gap-6"
398	    >
399	      {/* ── Views row + primary action ─────────────────────────────────────── */}
400	      <div className="flex items-end justify-between gap-4 border-b border-border">
401	        <div className="flex-1 min-w-0 overflow-x-auto scrollbar-none [mask-image:linear-gradient(to_right,transparent_0px,black_16px,black_calc(100%-16px),transparent_100%)] md:[mask-image:none]">
402	          {views.length > 0 ? (
403	            <ClientsViewTabs
404	              views={views}
405	              activeViewId={activeViewId}
406	              hasUnsavedChanges={hasUnsavedChanges}
407	              onViewChange={handleViewChange}
408	              onCreateView={() => {
409	                setViewManagerMode('create')
410	                setEditingView(null)
411	                setViewManagerOpen(true)
412	              }}
413	              onEditView={(view) => {
414	                setViewManagerMode('edit')
415	                setEditingView(view)
416	                setViewManagerOpen(true)
417	              }}
418	              onDuplicateView={handleDuplicateView}
419	              onDeleteView={handleDeleteView}
420	              onSetDefault={handleSetDefaultView}
421	            />
422	          ) : (
423	            <div className="h-10" aria-hidden="true" />
424	          )}
425	        </div>
426	        <div className="flex shrink-0 items-center gap-2 pb-2">
427	          {inactiveCount > 0 && (
428	            <span
429	              title={`${inactiveCount} client${inactiveCount !== 1 ? 's' : ''} not seen in 90+ days`}
430	              className="inline-flex items-center gap-1 rounded-full bg-destructive/10 text-destructive text-[11px] font-medium px-2 py-0.5 select-none"
431	            >
432	              <span className="h-1.5 w-1.5 rounded-full bg-destructive shrink-0" aria-hidden="true" />
433	              {inactiveCount} inactive
434	            </span>
435	          )}
436	          <Button size="sm" onClick={handleNewClient}>
437	            <Plus className="mr-1.5 h-3.5 w-3.5" aria-hidden="true" />
438	            New client
439	          </Button>
440	        </div>
441	      </div>
442	
443	      {/* ── Toolbar row (search + filters + sort + columns) ────────────────── */}
444	      <ClientsToolbar
445	        search={filters.q}
446	        onSearchChange={(q) => handleFiltersChange({ ...filters, q })}
447	        filters={filters}
448	        onFiltersChange={handleFiltersChange}
449	        sort={sort}
450	        onSortChange={setSort}
451	        columns={COLUMN_DEFS}
452	        visibleColumnKeys={visibleColumnKeys}
453	        onVisibleColumnsChange={setVisibleColumnKeys}
454	        tagLibrary={tagLibrary}
455	        showArchived={filters.showArchived}
456	        onToggleArchived={() => handleFiltersChange({ ...filters, showArchived: !filters.showArchived })}
457	      />
458	
459	      {/* ── Bulk actions ───────────────────────────────────────────────────── */}
460	      {selectedIds.length > 0 && (
461	        <BulkActionsBar
462	          selectedIds={selectedIds}
463	          tagLibrary={tagLibrary}
464	          onClearSelection={() => setSelectedIds([])}
465	          onArchived={() => void fetchClients(filters, 1, sort)}
466	          onTagsApplied={() => void fetchClients(filters, 1, sort)}
467	        />
468	      )}
469	
470	      {/* ── Table / empty / error ──────────────────────────────────────────── */}
471	      <DataState
472	        data={clients}
473	        isLoading={isInitialLoad}
474	        isError={!!fetchError && clients.length === 0}
475	        error={fetchError}
476	        loadingSlot={<TableSkeleton rows={8} />}
477	        emptySlot={
478	          hasActiveFilters || (activeViewId) ? (
479	            activeViewId ? (
480	              <EmptyState
481	                icon={BookmarkX}
482	                title="No clients match these filters"
483	                description={`The filters in "${views.find((v) => v.id === activeViewId)?.name ?? 'this view'}" returned no results.`}
484	                cta={{
485	                  label: 'Clear filters',
486	                  onClick: () => {
487	                    setFilters(DEFAULT_FILTERS)
488	                    setHasUnsavedChanges(false)
489	                  },
490	                }}
491	                ctaSecondary={{
492	                  label: 'Edit view filters',
493	                  onClick: () => {
494	                    const view = views.find((v) => v.id === activeViewId) ?? null
495	                    if (view) {
496	                      setViewManagerMode('edit')
497	                      setEditingView(view)
498	                      setViewManagerOpen(true)
499	                    }
500	                  },
501	                }}
502	                variant="no-results"
503	              />
504	            ) : (
505	              <EmptyState
506	                icon={SearchX}
507	                title="No clients match these filters"
508	                description="Try different filters or clear all to see everyone."
509	                cta={{
510	                  label: 'Clear filters',
511	                  onClick: () => {
512	                    setFilters(DEFAULT_FILTERS)
513	                    setHasUnsavedChanges(false)
514	                  },
515	                }}
516	                variant="no-results"
517	              />
518	            )
519	          ) : (
520	            <EmptyState
521	              icon={Users}
522	              title="Add your first client"
523	              description="Start with a manual entry — CSV import is coming soon."
524	              cta={{ label: '+ New client', onClick: handleNewClient }}
525	              ctaSecondary={{
526	                label: 'Import from CSV',
527	                onClick: () => toast.info('CSV import is coming soon. Add clients manually for now.'),
528	              }}
529	              variant="first-time"
530	            />
531	          )
532	        }
533	        errorSlot={
534	          <PageError
535	            error={fetchError ?? new Error('Failed to load clients')}
536	            reset={() => void fetchClients(filters, 1, sort)}
537	            variant="inline"
538	          />
539	        }
540	      >
541	        {(data) => (
542	          <ClientsTable
543	            clients={data}
544	            tagLibrary={tagLibrary}
545	            loading={loading && data.length === 0}
546	            selectedIds={selectedIds}
547	            onSelectionChange={setSelectedIds}
548	            onEdit={handleEditClient}
549	            onAddNote={(id) => setNoteClientId(id)}
550	          />
551	        )}
552	      </DataState>
553	
554	      {/* ── Load more + count footer ───────────────────────────────────────── */}
555	      {(hasMore || loading) && clients.length > 0 && (
556	        <div className="flex items-center justify-between py-4">
557	          <span className="text-sm text-muted-foreground tabular-nums">
558	            Showing {clients.length}{totalCount !== null ? ` of ${totalCount}` : ''} clients
559	          </span>
560	          {hasMore && (
561	            <Button variant="outline" size="sm" onClick={handleLoadMore} disabled={loading}>
562	              {loading && <Loader2 className="mr-2 h-4 w-4 animate-spin" aria-hidden="true" />}
563	              Load more
564	            </Button>
565	          )}
566	        </div>
567	      )}
568	      {/* Count footer when no "load more" is shown */}
569	      {!hasMore && !loading && clients.length > 0 && totalCount !== null && (
570	        <p className="text-xs text-muted-foreground text-right tabular-nums">
571	          Showing {clients.length} of {totalCount}
572	        </p>
573	      )}
574	
575	      <ClientDrawer
576	        open={drawerOpen}
577	        onOpenChange={(v) => {
578	          setDrawerOpen(v)
579	          if (!v) setEditingClient(null)
580	        }}
581	        client={editingClient}
582	        tagLibrary={tagLibrary}
583	        onSuccess={handleDrawerSuccess}
584	      />
585	
586	      {noteClientId && (
587	        <AddNoteModal
588	          open={Boolean(noteClientId)}
589	          onOpenChange={(v) => { if (!v) setNoteClientId(null) }}
590	          clientId={noteClientId}
591	        />
592	      )}
593	
594	      <SavedViewManager
595	        open={viewManagerOpen}
596	        onOpenChange={setViewManagerOpen}
597	        mode={viewManagerMode}
598	        view={editingView}
599	        currentFilters={filters}
600	        onSaved={handleViewSaved}
601	      />
602	    </PullToRefresh>
603	  )
604	}
